import{_t as e,it as t,n,rt as r}from"./chunks/framework.BzA9dy5I.js";import{t as i}from"./chunks/assets.odmLjbZW.js";var a=JSON.parse(`{"title":"Arquitectura","description":"","frontmatter":{},"headers":[],"relativePath":"referencia/arquitectura.md","filePath":"referencia/arquitectura.md"}`),o={name:`referencia/arquitectura.md`};function s(n,a,o,s,c,l){return e(),r(`div`,null,[...a[0]||=[t(`<h1 id="arquitectura" tabindex="-1">Arquitectura <a class="header-anchor" href="#arquitectura" aria-label="Permalink to “Arquitectura”">​</a></h1><p>Hyperion separa el estado del proceso de la herramienta que ejecuta cada tarea. Su núcleo no depende de Codex, Claude, Cursor ni de Olimpo.</p><h2 id="responsabilidades" tabindex="-1">Responsabilidades <a class="header-anchor" href="#responsabilidades" aria-label="Permalink to “Responsabilidades”">​</a></h2><table tabindex="0"><thead><tr><th>Componente</th><th>Responsabilidad</th></tr></thead><tbody><tr><td>Agente externo</td><td>Traducir la petición a un plan, ejecutar herramientas y registrar resultados reales</td></tr><tr><td>Adaptadores MCP y CLI</td><td>Conectar el agente con el mismo contrato local</td></tr><tr><td>Motor de dominio</td><td>Validar dependencias, decisiones, compuertas, datos y revisiones</td></tr><tr><td>Servicio HTTP y SQLite</td><td>Persistir el proceso y transmitir cambios al canvas mediante SSE</td></tr><tr><td>Canvas React</td><td>Mostrar el flujo y recoger decisiones humanas</td></tr><tr><td>Desktop Electron</td><td>Ejecutar el servicio local y presentar el canvas y la configuración</td></tr></tbody></table><h2 id="vista-archimate" tabindex="-1">Vista ArchiMate <a class="header-anchor" href="#vista-archimate" aria-label="Permalink to “Vista ArchiMate”">​</a></h2><p>Esta vista describe los componentes implementados y sus relaciones. El formato de ejecución del proceso es un perfil BPMN simplificado, separado de la notación arquitectónica.</p><p><img src="`+i+`" alt="Vista ArchiMate de los componentes implementados en Hyperion" width="1440" height="790"></p><p><a href="https://github.com/0vas/hiperion/tree/main/docs/architecture" target="_blank" rel="noreferrer">Modelo fuente y otras vistas</a>.</p><h2 id="del-chat-al-resultado" tabindex="-1">Del chat al resultado <a class="header-anchor" href="#del-chat-al-resultado" aria-label="Permalink to “Del chat al resultado”">​</a></h2><ol><li>El agente crea el plan desde la petición y comparte su enlace.</li><li>El motor calcula las tareas habilitadas y sus entradas.</li><li>El agente inicia tareas, ejecuta acciones con sus herramientas y envía evidencia.</li><li>El usuario responde o aprueba desde el canvas.</li><li>El agente lee el cambio, retoma el trabajo y registra el resultado.</li></ol><p>El servicio no lanza un agente en segundo plano. La actualización en vivo del canvas y la continuidad de una conversación son capacidades diferentes.</p><h2 id="datos-y-evolucion" tabindex="-1">Datos y evolución <a class="header-anchor" href="#datos-y-evolucion" aria-label="Permalink to “Datos y evolución”">​</a></h2><p>Cada tarea declara entradas y salidas tipadas. Las entradas pueden proceder del contexto, de un valor literal o de la salida de una tarea anterior. El servidor valida los valores, incluidas las listas de opciones permitidas.</p><p>Las operaciones usan identificadores para evitar duplicados en reintentos de transporte. Las revisiones evitan guardar decisiones sobre un estado desactualizado. Un cambio de plan conserva el historial y requiere revisión humana antes de continuar.</p><p><a href="https://github.com/0vas/hiperion/blob/main/docs/process-contract.md" target="_blank" rel="noreferrer">Contrato de procesos</a> · <a href="https://github.com/0vas/hiperion/tree/main/docs/decisions" target="_blank" rel="noreferrer">Decisiones de arquitectura</a></p>`,15)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};